        List<String> tok = new ArrayList<>();
        while (st.hasMoreTokens()) tok.add(st.nextToken());
        TreeNode root = null;
        if (!tok.isEmpty() && !tok.get(0).equals("null")) {
            root = new TreeNode(Long.parseLong(tok.get(0)));
            ArrayDeque<TreeNode> q = new ArrayDeque<>();
            q.add(root);
            int i = 1;
            while (!q.isEmpty() && i < tok.size()) {
                TreeNode u = q.poll();
                if (i < tok.size()) {
                    if (!tok.get(i).equals("null")) {
                        u.left = new TreeNode(Long.parseLong(tok.get(i)));
                        q.add(u.left);
                    }
                    i++;
                }
                if (i < tok.size()) {
                    if (!tok.get(i).equals("null")) {
                        u.right = new TreeNode(Long.parseLong(tok.get(i)));
                        q.add(u.right);
                    }
                    i++;
                }
            }
        }
        root = convertBst(root);
        if (root == null) {
            System.out.println("null");
            return;
        }
        List<String> out = new ArrayList<>();
        LinkedList<TreeNode> q = new LinkedList<>();
        q.add(root);
        while (!q.isEmpty()) {
            TreeNode u = q.poll();
            if (u == null) {
                out.add("null");
                continue;
            }
            out.add(String.valueOf(u.val));
            q.add(u.left);
            q.add(u.right);
        }
        while (!out.isEmpty() && out.get(out.size() - 1).equals("null")) out.remove(out.size() - 1);
        System.out.println(String.join(" ", out));
